    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] == goal:
                goal_coords = (i, j)
                break

    # Initialize a dictionary to store the abstract states
    abstract_states = {}

    # Iterate over each cell in the grid
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            # If the cell is not an obstacle and not the goal
            if grid[i][j] != "X" and grid[i][j] != goal:
                # Calculate the Manhattan distance to the goal
                manhattan_distance = abs(i - goal_coords[0]) + abs(j - goal_coords[1])

                # If this distance is already a key in the dictionary, append the current state to its value
                if manhattan_distance in abstract_states:
                    abstract_states[manhattan_distance].append(grid[i][j])
                # Otherwise, add it as a new key-value pair
                else:
                    abstract_states[manhattan_distance] = [grid[i][j]]

    # Convert the dictionary values to a list of lists and return it
    return list(abstract_states.values())

