def state_abstraction(grid_world):
    # Define the grid and goal
    grid = grid_world["grid"]
    goal = grid_world["goal"]

    # Find the position of the goal in the grid
    for i, row in enumerate(grid):
        for j, cell in enumerate(row):
            if cell == goal:
                goal_position = (i, j)

    # Initialize the abstraction groups
    abstraction_groups = [[0 for _ in range(len(grid[0]))] for _ in range(len(grid))]

    # Iterate over each cell in the grid
    for i, row in enumerate(grid):
        for j, cell in enumerate(row):
            if cell == "X":
                abstraction_groups[i][j] = -1  # Obstacles are not part of any group

            else:
                # Calculate the Manhattan distance to the goal
                distance_to_goal = abs(i - goal_position[0]) + abs(j - goal_position[1])

                # Group cells based on their distance to the goal
                abstraction_groups[i][j] = distance_to_goal

    return abstraction_groups


